    begin
        rst <= '1';
        wait for 3 * CLK_PERIOD;
        rst <= '0';
        wait for 112 * CLK_PERIOD;

        check_reg(regs, 5, x"DDCCBBAA", "x5", errors);
        check_reg(regs, 7, x"00001234", "x7", errors);
        check_reg(regs, 8, x"FFFF8000", "x8", errors);
        check_reg(regs, 9, x"00008000", "x9", errors);
        check_reg(regs, 10, x"00001234", "x10", errors);
        check_reg(regs, 11, x"12341234", "x11", errors);
        check_reg(regs, 13, x"DDCCBBAA", "x13", errors);

        finish_test("tb_all_stores", errors);
        wait;
    end process;
end architecture sim;
